// Motor de conciliación de EGRESOS GENERALES (grupo Contabilidad) — versión Postgres.
// Cruza comprobantes de egreso del grupo Contabilidad contra movimientos bancarios negativos,
// identifica al tercero (proveedor o colaborador de nómina) por la CUENTA DE DESTINO del
// comprobante —no por el número de OC, que un comprobante de transferencia normal no trae—,
// vincula factura/OC con su comprobante de pago cuando llegan por separado, y marca
// PROVEEDORES_LOCALES_PAGOS cuando aplica.
const docs = (function(){ try { return $('Leer comprobantes egresos').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const movs = (function(){ try { return $('Leer BANCOS_MOV').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const tpagos = (function(){ try { return $('Leer TRANSPORTES_PAGOS').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const provs = (function(){ try { return $('Leer PROVEEDORES_LOCALES_PAGOS').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const soportes = (function(){ try { return $('Leer soportes (factura/OC)').all().map(i => i.json).filter(x => x && x.ID_DOC); } catch(e) { return []; } })();
const terceros = (function(){ try { return $('Leer CAT_TERCEROS').all().map(i => i.json).filter(x => x && x.CUENTA_BANCARIA); } catch(e) { return []; } })();
const parseF = v => { if (!v) return null; if (v instanceof Date) return v;
  if (typeof v === 'number' && v > 20000 && v < 80000) return new Date(Date.UTC(1899,11,30) + Math.round(v)*86400000);
  const s = String(v).trim();
  if (/^\d+$/.test(s)) { const n = parseInt(s); if (n > 20000 && n < 80000) return new Date(Date.UTC(1899,11,30) + n*86400000); }
  let m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (m) return new Date(m[3] + '-' + m[2].padStart(2,'0') + '-' + m[1].padStart(2,'0'));
  const d2 = new Date(s.replace(' ', 'T')); return isNaN(d2) ? null : d2; };
const neto = p => { const v = parseFloat(p.PAGO_NETO); return isNaN(v) || !v ? parseFloat(p.VALOR) : v; };
const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const soloDigitos = s => String(s || '').replace(/\D/g, '');
const normCta = s => soloDigitos(s).replace(/^0+/, ''); // tolera ceros a la izquierda perdidos (Excel/OCR)
const mismoTercero = (a, b) => {
  const ta = norm(a).split(' ').filter(w => w.length > 3);
  const tb = norm(b).split(' ').filter(w => w.length > 3);
  return ta.length > 0 && ta.some(w => tb.includes(w));
};
// El extracto se sube con ~1 día de atraso, pero los comprobantes llegan al instante. Un comprobante sin
// movimiento bancario NO es un problema mientras el extracto cargado aún no llegue a su fecha: se deja en
// estado PROCESADO y se reintenta en silencio cada 30 min. Solo se alerta si (a) el extracto ya cubre la
// fecha del pago (con GRACIA_DIAS de margen por movimientos que el banco registra al día hábil siguiente)
// y aun así no aparece, o (b) pasaron más de ESPERA_MAX_H horas (red de seguridad: extracto sin subir).
const GRACIA_DIAS = 1;
const ESPERA_MAX_H = 72;
const ultimoExtracto = movs.filter(m => m.ORIGEN === 'EXTRACTO').map(m => parseF(m.FECHA)).filter(Boolean)
  .reduce((mx, f) => (!mx || f > mx ? f : mx), null);
const out = [];
const provsAbiertas = provs.filter(p => p.ESTADO_PAGO !== 'PAGADO'); // las OC ya pagadas no reciben pagos nuevos
const num = v => { const x = parseFloat(v); return isNaN(x) ? 0 : x; };
const ocNum = s => String(s.OC_NUM || '').replace(/\D/g, '');
// Total que realmente debe salir del banco por una OC: el total de la OC (subtotal + IVA - retenciones) si ya
// se aplicó; si no, el costo estimado de Symphony (sin IVA). Saldo = total - lo ya pagado en abonos previos.
const totalOC = p => num(p.OC_TOTAL_PAGAR) || num(p.VALOR_COSTO);
const saldoOC = p => totalOC(p) - num(p.VALOR_PAGADO);
const tolOC = t => Math.max(1, t * 0.02);
// Elige UN candidato: el que calza exacto en valor; si no, el único; si hay duda, ninguno (nunca adivinar).
const elegir = (lista, valorDoc) => {
  if (!lista.length) return null;
  const exacto = lista.filter(s => Math.abs(num(s.OCR_VALOR) - valorDoc) <= 1);
  if (exacto.length === 1) return exacto[0];
  return lista.length === 1 ? lista[0] : null;
};
for (const d of docs) {
  const val = parseFloat(d.OCR_VALOR);
  if (!val) { if (d.ESTADO !== 'SIN_MATCH') out.push({ json: { accion: 'ERROR', doc: d, motivo: 'OCR sin valor' } }); continue; }
  // Los soportes de transporte también pueden llegar a Contabilidad por error: si calza con un pago
  // de transporte pendiente, es territorio de WF-08, no de este motor.
  const esTransporte = tpagos.some(p => Math.abs(neto(p) - val) <= 1 || Math.abs(parseFloat(p.VALOR) - val) <= 1);
  if (esTransporte || d.CATEGORIA_GASTO === 'TRANSPORTE') continue;

  // ===== 1) ¿Quién recibió el pago? Por la CUENTA DE DESTINO del comprobante (un comprobante normal no trae la OC) =====
  const cuentaDoc = normCta(d.OCR_CUENTA_DESTINO);
  const tercero = cuentaDoc ? (terceros.find(t => String(t.CUENTA_BANCARIA).split(/[;,]/).some(x => normCta(x) === cuentaDoc)) || null) : null;
  const esNomina = !!(tercero && tercero.TIPO === 'COLABORADOR');

  // ===== 2) ¿Hay una OC/factura que respalde el pago? Se enviaron juntas o la OC se escribe en el caption. =====
  const tsDoc = (parseF(d.FECHA_RECIBIDO) || new Date()).getTime();
  const difH = s2 => { const t2 = parseF(s2.FECHA_RECIBIDO); return t2 ? Math.abs(t2.getTime() - tsDoc) / 3600000 : 9999; };
  const ocComprobante = String(d.OC_NUM || d.ID_COMPRA_INFORMADO || '').replace(/\D/g, '');
  const delTercero = s2 => !tercero || mismoTercero(s2.OCR_CLIENTE, tercero.NOMBRE);
  let soporte = null;
  if (!esNomina) {
    soporte =
      (ocComprobante ? soportes.find(s2 => ocNum(s2) === ocComprobante && difH(s2) <= 168) : null) || // misma OC explícita: hasta 7 días
      elegir(soportes.filter(s2 => s2.CLASIFICACION === 'ORDEN_COMPRA' && s2.REMITENTE_WA === d.REMITENTE_WA && difH(s2) <= 1 && delTercero(s2)), val) || // OC enviada junto con el comprobante (misma tanda, 1 h)
      (tercero ? elegir(soportes.filter(s2 => mismoTercero(s2.OCR_CLIENTE, tercero.NOMBRE) && difH(s2) <= 168), val) : null) || // mismo proveedor vía cuenta: hasta 7 días
      soportes.find(s2 => s2.REMITENTE_WA === d.REMITENTE_WA && s2.OCR_VALOR && String(s2.OCR_VALOR) === String(d.OCR_VALOR) && difH(s2) <= 24) || // mismo valor + remitente: 24 h
      soportes.find(s2 => s2.OCR_VALOR && String(s2.OCR_VALOR) === String(d.OCR_VALOR) && difH(s2) <= 1) || null; // mismo valor, 1 h
  }
  const ocExplicito = ocComprobante || (soporte && soporte.CLASIFICACION === 'ORDEN_COMPRA' ? ocNum(soporte) : '');

  // ===== 3) ¿Paga una OC de un proveedor local? Cada OC es independiente (un pedido, un proveedor). =====
  let provLocal = null;
  // Si el comprobante ya se registró como pago (porque llegó antes que el extracto), la OC ya está resuelta.
  const yaRegistrada = !!d.PAGO_ID_CONTROL;
  if (yaRegistrada) provLocal = provs.find(p => String(p.ID_CONTROL) === String(d.PAGO_ID_CONTROL)) || null;
  if (!provLocal && !esNomina && ocExplicito) {
    const deLaOC = provsAbiertas.filter(p => String(p.ID_COMPRA) === ocExplicito);
    const delProv = tercero ? deLaOC.filter(p => String(p.NIT_PROVEEDOR) === String(tercero.NIT)) : [];
    const porNombre = soporte ? deLaOC.filter(p => mismoTercero(p.PROVEEDOR_NOMBRE, soporte.OCR_CLIENTE)) : [];
    const base = delProv.length ? delProv : (porNombre.length ? porNombre : deLaOC);
    provLocal = base.length === 1 ? base[0] : null; // varios proveedores en la misma compra y sin forma de distinguirlos: revisión humana
  }
  if (!provLocal && !esNomina && tercero && tercero.TIPO === 'PROVEEDOR_LOCAL') {
    // Sin OC explícita: entre las OC pendientes de ESE proveedor, la que calza con el valor pagado como
    // pago total de la OC, como saldo pendiente tras un abono previo, o como el 50% de anticipo.
    // Solo se asigna si hay UNA candidata (o una sola deuda pendiente); si hay duda, no se adivina.
    const deudas = provsAbiertas.filter(p => String(p.NIT_PROVEEDOR) === String(tercero.NIT));
    const calza = deudas.filter(p => { const t = totalOC(p);
      return Math.abs(val - t) <= tolOC(t) || Math.abs(val - saldoOC(p)) <= tolOC(t) || Math.abs(val - t / 2) <= 1; });
    provLocal = calza.length === 1 ? calza[0] : (deudas.length === 1 ? deudas[0] : null);
  }
  const catFinal = esNomina ? 'NOMINA' : ((soporte && soporte.CLASIFICACION === 'ORDEN_COMPRA') ? 'COMPRA_PROVEEDOR' : (d.CATEGORIA_GASTO || (soporte && soporte.CATEGORIA_GASTO) || 'GASTO_GENERAL'));
  const tercFinal = (tercero && tercero.NOMBRE) || (soporte && soporte.OCR_CLIENTE) || d.OCR_CLIENTE || '';
  const ocFinal = (soporte && soporte.OC_NUM) || d.OC_NUM || (provLocal && provLocal.ID_COMPRA) || '';
  // Si el pago ya estaba registrado, VALOR_PAGADO ya lo incluye.
  const pagadoAntes = provLocal ? num(provLocal.VALOR_PAGADO) - (yaRegistrada ? val : 0) : 0;
  const info = provLocal ? { totalOC: totalOC(provLocal), pagadoAntes, pagadoDespues: pagadoAntes + val } : {};
  const esAbono = provLocal ? (pagadoAntes + val) < totalOC(provLocal) - 1 : false;

  // ===== 4) ¿Existe el movimiento en el banco? valor exacto (±1), fecha ±3 días, sin conciliación previa =====
  const fechaDoc = parseF(d.OCR_FECHA_PAGO);
  let candidatos = movs.filter(m => {
    if (m.ID_CONCILIACION) return false;
    const mv = parseFloat(m.VALOR);
    if (isNaN(mv) || mv >= 0) return false;
    if (Math.abs(Math.abs(mv) - val) > 1) return false;
    const fm = parseF(m.FECHA);
    if (fechaDoc && fm) { const diff = Math.abs((fm - fechaDoc) / 86400000); if (diff > 3) return false; }
    return true;
  });
  // Desempate por OC/ID en referencia del extracto, luego por nombre del beneficiario
  if (candidatos.length > 1 && d.OC_NUM) {
    const byOC = candidatos.filter(m => (String(m.REFERENCIA||'') + ' ' + String(m.DESCRIPCION||'')).includes(String(d.OC_NUM).replace(/\D/g,'')));
    if (byOC.length >= 1) candidatos = byOC;
  }
  if (candidatos.length > 1 && d.OCR_CLIENTE) {
    const toks = norm(d.OCR_CLIENTE).split(' ').filter(w => w.length > 3);
    const byName = candidatos.filter(m => toks.some(w => norm(m.DESCRIPCION + ' ' + m.TERCERO).includes(w)));
    if (byName.length >= 1) candidatos = byName;
  }
  if (candidatos.length === 0) {
    // El comprobante de Telegram YA es un pago real y verificable: si paga una OC, se registra de una vez
    // como pago (aunque el extracto aún no llegue). Cuando el movimiento aparezca, se confirma (fuente AMBOS).
    if (provLocal && !d.PAGO_REGISTRADO) {
      out.push({ json: { accion: 'REGISTRAR_PAGO', doc: d, provLocal, valor: val, ocFinal, info, esAbono } });
    }
    if (d.ESTADO === 'SIN_MATCH') continue; // ya se alertó una vez: reintento silencioso
    const fRef = fechaDoc || parseF(d.FECHA_RECIBIDO);
    const recibido = parseF(d.FECHA_RECIBIDO);
    const edadH = recibido ? (Date.now() - recibido.getTime()) / 3600000 : 0;
    const cubierto = !!(fRef && ultimoExtracto && ultimoExtracto.getTime() >= fRef.getTime() + GRACIA_DIAS * 86400000);
    if (fRef && !cubierto && edadH <= ESPERA_MAX_H) continue; // el extracto aún no llega a esa fecha: esperar en silencio
    out.push({ json: { accion: 'SIN_MATCH', doc: d, motivo: cubierto
      ? 'El extracto ya cubre esa fecha y no aparece el movimiento.'
      : (fRef ? 'Hace más de ' + ESPERA_MAX_H + ' h y no aparece en el extracto (¿falta subirlo?).' : 'Sin fecha legible en el comprobante y sin movimiento en el extracto.') } });
    continue;
  }
  if (candidatos.length > 1) {
    out.push({ json: { accion: 'AMBIGUO', doc: d, motivo: candidatos.length + ' movimientos candidatos' } });
    continue;
  }
  out.push({ json: { accion: 'MATCH', doc: d, mov: candidatos[0], provLocal: provLocal || null,
    esAbonoProveedor: esAbono, valor: val, catFinal, tercFinal, ocFinal, soporte: soporte || null, info } });
  if (soporte) out.push({ json: { accion: 'CERRAR_SOPORTE', soporteId: soporte.ID_DOC, pagoId: d.ID_DOC } });
}
return out;

parameters.query:
update bancos_mov set categoria = $2::text, tercero = $3::text, factura_oc = $4::text,
  detalle = $5::text, id_conciliacion = $6::text, updated_at = now()
where id_mov = $1::text;

update comprobantes_wa set id_mov_match = $2::text, estado = 'CONCILIADO_EGRESO',
  human_review = 'PENDIENTE', updated_at = now()
where id_doc = $1::text;

