parameters.query:
update comprobantes_wa set estado = 'SOPORTE_VINCULADO', id_mov_match = $2::text,
  notas = $3::text, updated_at = now()
where id_doc = $1::text;

insert into pagos_oc (id_control, id_compra, nit_proveedor, valor, fecha_pago, fuente, id_doc_wa, notas)
values ($1::text, $2::text, $3::text, $4::numeric, nullif($5::text,'')::date, 'COMPROBANTE', $6::text, $7::text)
on conflict (id_doc_wa) where id_doc_wa is not null do nothing;
